import math

def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    return dot / (math.hypot(*a) * math.hypot(*b))

query = [1.0, 1.0, 0.0]
docs = {
    "returns-policy": [2.0, 2.0, 0.0],
    "shipping-times": [0.0, 1.0, 1.0],
    "warranty": [1.0, 0.0, 0.0],
    "careers": [0.0, 0.0, 3.0],
}
ranked = sorted(docs, key=lambda d: cosine(query, docs[d]), reverse=True)
for d in ranked:
    print(d, round(cosine(query, docs[d]), 3))
